insert into hygieia.exercises (id, slug, name_el, name_en, cue_el, cue_en, workout_type, level, muscle_groups, equipment_el, equipment_en) values
  ('9d75a6d4-0f5f-f53e-a9a4-0b2035a8499f'::uuid, 'a-skips', 'A-skips', 'A-skips', 'Κάντε skip προς τα εμπρός ανεβάζοντας το ένα γόνατο με το αντίθετο χέρι και φέρνοντας το πέλμα γρήγορα κάτω από τους γοφούς. Μείνετε όρθιοι και ελαστικοί· εκπνεύστε σε κάθε ώθηση.', 'Skip forward driving one knee up with the opposite arm, snapping the foot back down under the hips. Stay tall and bouncy; exhale with each drive.', 'running', 'advanced', array['hip-flexors','calves','cardio']::text[], null, null),
  ('8a9ef55f-3052-5b5d-1c10-00d03a0a3e25'::uuid, 'ankle-circles', 'Κύκλοι αστραγάλων', 'Ankle circles', 'Σηκώστε το ένα πόδι και γυρίστε τον αστράγαλο αργά 10 φορές προς κάθε κατεύθυνση, μετά αλλάξτε. Ομαλή κίνηση και κανονική αναπνοή.', 'Lift one foot and circle the ankle slowly 10 times each way, then switch. Keep the movement smooth and breathe normally.', 'mobility', 'beginner', array['calves']::text[], null, null),
  ('a80931a2-2864-10e5-a952-a40416e75188'::uuid, 'archer-push-up', 'Κάμψεις τοξότη', 'Archer push-up', 'Χέρια ανοιχτά, κατεβείτε προς το ένα χέρι ενώ το άλλο τεντώνει στο πλάι, σπρώξτε πίσω στο κέντρο και εναλλάξτε. Εκπνεύστε στο σπρώξιμο και κρατήστε τους γοφούς σταθερούς.', 'Hands wide, lower toward one hand while the other arm straightens to the side, then push back to centre and alternate. Exhale on the push and keep the hips level.', 'calisthenics', 'advanced', array['chest','triceps','shoulders','core']::text[], null, null),
  ('29f788f3-fc52-458b-faa9-e02518a15df8'::uuid, 'arm-circles', 'Κύκλοι χεριών', 'Arm circles', 'Σταθείτε όρθιοι και κάντε αργούς κύκλους με τεντωμένα χέρια, από μικρούς σε μεγάλους, μετά αντίστροφα. Αναπνέετε άνετα και κρατήστε τους ώμους μακριά από τα αυτιά.', 'Stand tall and draw slow circles with straight arms, small to large, then reverse. Breathe easily and keep the shoulders away from the ears.', 'home', 'beginner', array['shoulders']::text[], null, null),
  ('6d4356f5-dc4d-a969-a953-df6be869bf77'::uuid, 'assisted-squat', 'Υποβοηθούμενα καθίσματα', 'Assisted squat', 'Κρατηθείτε ελαφρά από κολόνα ή κάσα πόρτας, καθίστε όσο βαθιά είναι άνετο με τις φτέρνες κάτω και το στήθος ψηλά. Χρησιμοποιήστε τα χέρια μόνο όσο χρειάζεται και εκπνεύστε καθώς σηκώνεστε.', 'Hold a pole or door frame lightly, sit back as deep as comfortable with heels down and chest up. Use the hands only as much as needed and exhale as you stand.', 'calisthenics', 'beginner', array['quads','glutes']::text[], null, null),
  ('416ff2d7-d7a6-27fa-dfb7-3693750d54ab'::uuid, 'australian-row', 'Αυστραλέζικες έλξεις (οριζόντιες)', 'Australian row (inverted row)', 'Κρεμαστείτε κάτω από χαμηλή μπάρα με τις φτέρνες στο πάτωμα και σώμα ευθεία, τραβήξτε το στήθος στη μπάρα σφίγγοντας τις ωμοπλάτες. Εκπνεύστε στο τράβηγμα, κατεβείτε αργά.', 'Hang under a low bar with heels on the floor and body straight, pull the chest to the bar squeezing the shoulder blades. Exhale on the pull, lower slowly.', 'calisthenics', 'beginner', array['back','biceps','core']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('344c905d-c87a-b9a5-e172-2bbe6bd03118'::uuid, 'backstroke-easy', 'Χαλαρό ύπτιο', 'Easy backstroke', 'Επιπλεύστε ανάσκελα με τους γοφούς ψηλά και τα αυτιά στο νερό, εναλλάξτε χεριές με τεντωμένα χέρια και σταθερή ποδιά. Αναπνέετε ελεύθερα και κοιτάτε ευθεία πάνω.', 'Float on your back with the hips high and ears in the water, alternate straight-arm pulls with a steady kick. Breathe freely and look straight up.', 'swimming', 'beginner', array['back','shoulders','core']::text[], null, null),
  ('c120439d-932c-8ddc-c51e-3f451558c804'::uuid, 'band-shoulder-dislocates', 'Περάσματα ώμων με λάστιχο', 'Band shoulder pass-throughs', 'Κρατήστε λάστιχο με ανοιχτή λαβή και τεντωμένα χέρια, σηκώστε το αργά πάνω από το κεφάλι και πίσω, μετά ξανά μπροστά. Ανοίξτε τη λαβή αν τσιμπάει και αναπνέετε σταθερά.', 'Hold a band wide with straight arms and lift it slowly overhead and behind you, then back to the front. Widen the grip if it pinches and breathe steadily.', 'mobility', 'intermediate', array['shoulders','chest']::text[], 'Λάστιχο αντίστασης', 'Resistance band'),
  ('a9d12d5b-f97c-5327-bf1b-4f0b13b01531'::uuid, 'barbell-back-squat', 'Καθίσματα με μπάρα', 'Barbell back squat', 'Μπάρα στην πάνω πλάτη, σφίξτε τον κορμό με βαθιά εισπνοή, καθίστε μέχρι οι γοφοί να περάσουν κάτω από τα γόνατα με στήθος ψηλά και γόνατα ανοιχτά. Εκπνεύστε στο δύσκολο σημείο της ανόδου.', 'Bar on the upper back, brace the core with a big breath, squat until the hips are below the knees with the chest up and knees out. Exhale through the sticking point on the way up.', 'gym', 'advanced', array['quads','glutes','hamstrings','core']::text[], 'Μπάρα', 'Barbell'),
  ('80b0b2ca-1c44-d897-7b23-39a50805ae1a'::uuid, 'barbell-bench-press', 'Πιέσεις πάγκου με μπάρα', 'Barbell bench press', 'Ωμοπλάτες σφιγμένες, πέλματα σταθερά, κατεβάστε τη μπάρα ελεγχόμενα στο κάτω στήθος και πιέστε πίσω πάνω από τους ώμους. Εισπνοή στην κάθοδο, εκπνοή στην πίεση· πάντα με βοηθό ή ασφάλειες.', 'Shoulder blades pinched, feet planted, lower the bar to the lower chest with control and press back over the shoulders. Inhale down, exhale on the press; always use a spotter or safeties.', 'gym', 'advanced', array['chest','triceps','shoulders']::text[], 'Μπάρα', 'Barbell'),
  ('ff3ac96c-8b11-1e54-d73a-b0be90f3eb06'::uuid, 'barbell-row', 'Κωπηλατική με μπάρα', 'Barbell row', 'Κάμψη περίπου στις 45 μοίρες με ίσια πλάτη, τραβήξτε τη μπάρα στο κάτω στήθος με τους αγκώνες κοντά και σφίξτε τις ωμοπλάτες. Εκπνεύστε στο τράβηγμα, κατεβάστε ελεγχόμενα.', 'Hinge to about 45 degrees with a flat back, pull the bar to the lower chest with the elbows close and squeeze the shoulder blades. Exhale on the pull, lower under control.', 'gym', 'intermediate', array['back','biceps']::text[], 'Μπάρα', 'Barbell'),
  ('f6c6224d-43b6-cbab-ec14-ec39a2b4c774'::uuid, 'bench-dip', 'Βυθίσεις σε πάγκο', 'Bench dip', 'Χέρια στην άκρη του πάγκου πίσω σας, κατεβάστε τους γοφούς μέχρι οι αγκώνες να φτάσουν στις 90 μοίρες, κρατώντας τους ώμους κάτω. Εκπνεύστε καθώς σπρώχνετε πάνω.', 'Hands on the bench edge behind you, lower the hips until the elbows reach 90 degrees, keeping the shoulders down. Exhale as you press back up.', 'calisthenics', 'intermediate', array['triceps','chest','shoulders']::text[], 'Πάγκος', 'Bench'),
  ('9b4cc01b-8a1a-72ff-288d-2d470690d194'::uuid, 'bobbing-breath-practice', 'Άσκηση αναπνοής με βυθίσεις', 'Bobbing breath practice', 'Σε νερό μέχρι το στήθος, βυθιστείτε και φυσήξτε σταθερά φυσαλίδες από μύτη και στόμα, βγείτε για μια γρήγορη εισπνοή και επαναλάβετε. Κάντε την εκπνοή αργή και πλήρη.', 'In chest-deep water, sink under and blow bubbles steadily out of the nose and mouth, surface for a quick breath and repeat. Make the exhale slow and complete.', 'swimming', 'beginner', array['cardio']::text[], null, null),
  ('13f818b1-44cf-c25f-2794-61251c587958'::uuid, 'bodyweight-squat', 'Καθίσματα χωρίς βάρος', 'Bodyweight squat', 'Πόδια στο άνοιγμα των ώμων, καθίστε με τους γοφούς πίσω και κάτω, στήθος ψηλά και γόνατα στην κατεύθυνση των δακτύλων. Εισπνοή στην κάθοδο, εκπνοή καθώς σηκώνεστε.', 'Feet shoulder-width, sit the hips back and down with the chest up and knees tracking over the toes. Inhale on the way down, exhale as you stand.', 'home', 'beginner', array['quads','glutes']::text[], null, null),
  ('5b16c07e-2fe3-e913-3c48-648ee358c8d1'::uuid, 'breaststroke-100m', 'Πρόσθιο, 100 μέτρα', 'Breaststroke, 100 m', 'Χεριά, αναπνοή, ποδιά, γλίστρημα: ανοίξτε και κλείστε τα χέρια, σηκωθείτε για αναπνοή, κλείστε τα πόδια δυνατά και κρατήστε μακρύ streamline πριν την επόμενη χεριά. Εκπνεύστε στο γλίστρημα.', 'Pull, breathe, kick, glide: sweep the hands out and in, lift to breathe, whip the legs together and hold a long streamline before the next stroke. Exhale during the glide.', 'swimming', 'intermediate', array['chest','adductors','cardio']::text[], null, null),
  ('1f8f7410-692b-8a83-1f93-e9b359d0bdb9'::uuid, 'bridge-pose', 'Στάση γέφυρας', 'Bridge pose', 'Ξαπλωμένοι ανάσκελα με τα πέλματα κοντά στους γοφούς, σηκώστε τους γοφούς ψηλά και πλέξτε τα χέρια από κάτω, ανοίγοντας το στήθος. Αναπνέετε αργά για 20–30 δευτερόλεπτα και κατεβείτε σπόνδυλο-σπόνδυλο.', 'Lying on your back with feet close to the hips, press the hips high and interlace the hands beneath you, opening the chest. Breathe slowly for 20–30 seconds and lower one vertebra at a time.', 'mobility', 'advanced', array['hip-flexors','back','shoulders','glutes']::text[], 'Στρώμα', 'Mat'),
  ('cd2b5fe9-e706-5b85-fd27-2f6d35d27fb9'::uuid, 'brisk-walk-5min', 'Γρήγορο περπάτημα, 5 λεπτά', 'Brisk walk, 5 min', 'Περπατήστε σε ρυθμό που σας ζεσταίνει χωρίς να σας κόβει την ανάσα, με τα χέρια να κινούνται ελεύθερα. Αναπνέετε από τη μύτη και χαλαρώστε τους ώμους.', 'Walk at a pace that warms you without leaving you breathless, arms swinging freely. Breathe through the nose and loosen the shoulders.', 'running', 'beginner', array['cardio']::text[], null, null),
  ('7ea9c006-bb4f-10dd-1043-ad649150a883'::uuid, 'bulgarian-split-squat', 'Βουλγαρικά καθίσματα', 'Bulgarian split squat', 'Πίσω πόδι σε καρέκλα, κατεβείτε κάθετα μέχρι ο μπροστινός μηρός να είναι παράλληλος, κορμός ψηλά. Σπρώξτε με τη μπροστινή φτέρνα και εκπνεύστε καθώς σηκώνεστε.', 'Rear foot on a chair, lower straight down until the front thigh is parallel, torso tall. Drive through the front heel and exhale as you stand.', 'home', 'advanced', array['quads','glutes','hamstrings']::text[], 'Καρέκλα', 'Chair'),
  ('10e939c8-0373-a377-880e-a466bcc3ef81'::uuid, 'burpees', 'Burpees', 'Burpees', 'Καθίστε, πετάξτε τα πόδια πίσω σε σανίδα, κάντε μία κάμψη, φέρτε τα πόδια μπροστά και αναπηδήστε με τα χέρια ψηλά. Προσγειωθείτε απαλά και κρατήστε ρυθμική αναπνοή.', 'Squat down, jump the feet back to a plank, do a push-up, jump the feet in and leap up with arms overhead. Land softly and keep the breathing rhythmic.', 'home', 'advanced', array['full-body','cardio']::text[], null, null),
  ('5a1c3dd8-f13d-113a-8461-c4a7f92fbca1'::uuid, 'butt-kicks', 'Φτέρνες στους γλουτούς', 'Butt kicks', 'Τρέξτε επί τόπου φέρνοντας τις φτέρνες προς τους γλουτούς με γρήγορα, ελαφριά βήματα και όρθιο κορμό. Κρατήστε τα γόνατα να δείχνουν κάτω και αναπνέετε ρυθμικά.', 'Jog in place flicking the heels toward the glutes with quick, light steps and a tall torso. Keep the knees pointing down and breathe rhythmically.', 'running', 'intermediate', array['hamstrings','cardio']::text[], null, null),
  ('8d0b9168-7c3d-649b-0f22-b0fa9a5ca67f'::uuid, 'butterfly-25m', 'Πεταλούδα, 25 μέτρα', 'Butterfly, 25 m', 'Δύο ποδιές ανά κύκλο χεριών: πιέστε το στήθος κάτω όταν μπαίνουν τα χέρια, κλωτσήστε ξανά όταν βγαίνουν, και αναπνεύστε χαμηλά και μπροστά κάθε δεύτερη χεριά. Κρατήστε τον ρυθμό, μην πιέζετε.', 'Two kicks per arm cycle: press the chest down as the hands enter, kick again as they exit, and breathe low and forward every second stroke. Keep the stroke rhythmic, not forced.', 'swimming', 'advanced', array['chest','back','shoulders','core']::text[], null, null),
  ('830a5c07-5d5c-cfbd-6fba-3db9f2b3e973'::uuid, 'cable-face-pull', 'Face pull σε τροχαλία', 'Cable face pull', 'Ρυθμίστε το σχοινί στο ύψος του προσώπου, τραβήξτε προς το μέτωπο με τους αγκώνες ψηλά και ανοιχτά, σφίγγοντας τους πίσω ώμους. Εκπνεύστε στο τράβηγμα και επιστρέψτε αργά.', 'Set the rope at face height, pull toward the forehead with the elbows high and wide, squeezing the rear shoulders. Exhale on the pull and return slowly.', 'gym', 'intermediate', array['shoulders','back']::text[], 'Τροχαλία', 'Cable machine'),
  ('1a3ab89b-c634-85da-3665-24713e11c136'::uuid, 'cadence-drill-100rpm', 'Άσκηση ρυθμού, 100 στροφές/λεπτό', 'Cadence drill, 100 rpm', 'Σε ελαφριά σχέση, γυρίστε περίπου 100 στροφές το λεπτό για 2–3 λεπτά κρατώντας τους γοφούς ακίνητους και το πετάλι κυκλικό. Αποκατάσταση σε χαλαρό ρυθμό και βαθιά αναπνοή.', 'In a light gear, spin at about 100 rpm for 2–3 minutes keeping the hips still and the pedal stroke round. Recover at an easy cadence and breathe deeply.', 'cycling', 'intermediate', array['quads','hamstrings','cardio']::text[], 'Ποδήλατο', 'Bicycle'),
  ('fff10de8-5867-f045-2108-4c424b994711'::uuid, 'cadence-drill-90rpm', 'Άσκηση ρυθμού, 90 στροφές/λεπτό', 'Cadence drill, 90 rpm', 'Επιλέξτε ελαφριά σχέση και κρατήστε περίπου 90 στροφές το λεπτό για 3 λεπτά χωρίς να αναπηδάτε στη σέλα. Χαλαρώστε τα πέλματα και αναπνέετε σταθερά.', 'Choose an easy gear and hold about 90 pedal revolutions per minute for 3 minutes without bouncing in the saddle. Relax the feet and breathe steadily.', 'cycling', 'beginner', array['quads','hamstrings','cardio']::text[], 'Ποδήλατο', 'Bicycle'),
  ('defc4c7f-dc67-1c0b-f49c-037c3c832051'::uuid, 'calf-stretch-wall', 'Διάταση γαστροκνημίων στον τοίχο', 'Wall calf stretch', 'Χέρια στον τοίχο, κάντε βήμα πίσω με τη φτέρνα κάτω και το γόνατο τεντωμένο μέχρι να τεντώσει η γάμπα. Αναπνέετε αργά, κρατήστε 30 δευτερόλεπτα, μετά λυγίστε ελαφρά το πίσω γόνατο για την κάτω γάμπα.', 'Hands on the wall, step one foot back with the heel down and the knee straight until the calf stretches. Breathe slowly, hold 30 seconds, then bend the back knee slightly for the lower calf.', 'running', 'beginner', array['calves']::text[], null, null),
  ('0536e075-bd72-93f5-2aff-64424b8a9527'::uuid, 'cat-cow', 'Γάτα–αγελάδα', 'Cat–cow', 'Στα τέσσερα, εισπνεύστε καθώς χαμηλώνετε την κοιλιά και σηκώνετε το βλέμμα, εκπνεύστε καθώς στρογγυλεύετε τη σπονδυλική στήλη και μαζεύετε το πηγούνι. Κινηθείτε αργά, μία αναπνοή ανά θέση.', 'On all fours, inhale as you drop the belly and lift the gaze, exhale as you round the spine and tuck the chin. Move slowly, one breath per position.', 'mobility', 'beginner', array['back','core']::text[], 'Στρώμα', 'Mat'),
  ('96d74b30-9823-6494-db53-8e61111d4a06'::uuid, 'chest-doorway-stretch', 'Διάταση στήθους σε πόρτα', 'Doorway chest stretch', 'Πήχεις στην κάσα της πόρτας με τους αγκώνες στο ύψος των ώμων, κάντε ένα βήμα μπροστά μέχρι να ανοίξει το στήθος. Αναπνέετε αργά και κρατήστε 30 δευτερόλεπτα.', 'Forearms on the door frame with elbows at shoulder height, step one foot through until the chest opens. Breathe slowly and hold 30 seconds.', 'calisthenics', 'beginner', array['chest','shoulders']::text[], null, null),
  ('8138a070-42ac-f182-6dde-d411080eda5a'::uuid, 'chest-press-machine', 'Πιέσεις στήθους σε μηχάνημα', 'Chest press machine', 'Ρυθμίστε τις λαβές στο ύψος του στήθους, σπρώξτε μέχρι τα χέρια να είναι σχεδόν τεντωμένα και επιστρέψτε αργά. Εκπνεύστε στο σπρώξιμο και κρατήστε τις ωμοπλάτες πίσω.', 'Set the handles at mid-chest height, press forward until the arms are almost straight and return slowly. Exhale on the press and keep the shoulder blades back.', 'gym', 'beginner', array['chest','triceps','shoulders']::text[], 'Μηχάνημα', 'Machine'),
  ('245148d9-b69f-0e96-994f-2d8e77567bf6'::uuid, 'chest-to-bar-pull-up', 'Έλξεις μέχρι το στήθος', 'Chest-to-bar pull-up', 'Τραβήξτε εκρηκτικά μέχρι το στήθος να ακουμπήσει τη μπάρα, γέρνοντας ελαφρά πίσω στην κορυφή, και κατεβείτε ελεγχόμενα. Εκπνεύστε στο τράβηγμα· είναι η προϋπόθεση για το muscle-up.', 'Pull explosively until the chest touches the bar, leaning back slightly at the top, then lower under control. Exhale on the pull; this is the muscle-up prerequisite.', 'calisthenics', 'advanced', array['back','biceps','core']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('1a848070-1b2b-17aa-049a-efed8dc8dae1'::uuid, 'childs-pose', 'Στάση του παιδιού', 'Child''s pose', 'Γονατίστε, καθίστε με τους γοφούς στις φτέρνες και τεντώστε τα χέρια μπροστά με το μέτωπο να ακουμπά κάτω. Αναπνέετε αργά προς την πλάτη για 30–60 δευτερόλεπτα.', 'Kneel, sit the hips back onto the heels and stretch the arms forward with the forehead resting down. Breathe slowly into the back for 30–60 seconds.', 'mobility', 'beginner', array['back','shoulders','glutes']::text[], 'Στρώμα', 'Mat'),
  ('a43f15cb-bde1-af4a-378f-80849234a64a'::uuid, 'cossack-squat', 'Κοζάκικα καθίσματα', 'Cossack squat', 'Σταθείτε με ανοιχτά πόδια, μεταφέρετε όλο το βάρος στο ένα πόδι και καθίστε βαθιά πάνω του ενώ το άλλο μένει τεντωμένο με τα δάχτυλα πάνω. Εκπνεύστε στη μεταφορά, φτέρνα κάτω.', 'Stand wide, shift all your weight onto one leg and sit deep over it while the other leg stays straight with toes up. Exhale as you shift, keep the heel down.', 'mobility', 'advanced', array['adductors','glutes','quads','hamstrings']::text[], null, null),
  ('2332b377-9d24-8b6d-c1f9-6fcb412f3929'::uuid, 'couch-stretch', 'Διάταση couch', 'Couch stretch', 'Γονατίστε με τη μία κνήμη όρθια στον τοίχο ή στον καναπέ και το άλλο πόδι μπροστά, σφίξτε τον γλουτό του πίσω ποδιού και σηκώστε τον κορμό. Αναπνέετε αργά για 60 δευτερόλεπτα ανά πλευρά· υποχωρήστε αν πονάει το γόνατο.', 'Kneel with one shin up against a wall or couch and the other foot forward, squeeze the glute of the back leg and lift the torso tall. Breathe slowly for 60 seconds per side; back off if the knee hurts.', 'mobility', 'advanced', array['quads','hip-flexors']::text[], 'Στρώμα', 'Mat'),
  ('ecfd9534-ba3d-0340-9174-e9187d7988e2'::uuid, 'dead-hang', 'Παθητικό κρέμασμα', 'Dead hang', 'Πιάστε τη μπάρα στο άνοιγμα των ώμων και κρεμαστείτε με τεντωμένα χέρια, ώμοι χαλαροί, πόδια στον αέρα. Αναπνέετε αργά και κρατήστε με χρόνο για να δυναμώσει η λαβή.', 'Grip the bar shoulder-width and hang with straight arms, shoulders relaxed, feet off the floor. Breathe slowly and hold for time to build grip.', 'calisthenics', 'beginner', array['forearms','back','shoulders']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('9bf232ad-be8a-6279-fafa-1635430a33c9'::uuid, 'deadlift', 'Άρσεις θανάτου', 'Deadlift', 'Μπάρα πάνω από το μέσο του πέλματος, γοφοί ψηλότερα από τα γόνατα, ίσια πλάτη και ώμοι πάνω από τη μπάρα. Σφίξτε, σπρώξτε το πάτωμα και σηκωθείτε όρθιοι· εκπνεύστε στην κορυφή και κατεβάστε κατά μήκος των ποδιών.', 'Bar over mid-foot, hips higher than knees, flat back and shoulders over the bar. Brace, push the floor away and stand tall; exhale at the top and lower along the legs.', 'gym', 'advanced', array['hamstrings','glutes','back','core']::text[], 'Μπάρα', 'Barbell'),
  ('e75ba9f8-266e-2ace-0ca1-535a852928c2'::uuid, 'deep-squat-hold', 'Κράτημα βαθέος καθίσματος', 'Deep squat hold', 'Βυθιστείτε στο βαθύτερο κάθισμα που μπορείτε με τις φτέρνες κάτω, οι αγκώνες σπρώχνουν απαλά τα γόνατα προς τα έξω και το στήθος ψηλά. Αναπνέετε αργά για 30–60 δευτερόλεπτα· κρατηθείτε αν χρειάζεται.', 'Sink into the deepest squat you can with heels down, elbows pressing the knees gently outward and the chest tall. Breathe slowly for 30–60 seconds; hold a support if needed.', 'mobility', 'intermediate', array['hip-flexors','adductors','calves','quads']::text[], null, null),
  ('8238d9b3-e97a-1181-1a37-24fb89e50b35'::uuid, 'diamond-push-up', 'Κάμψεις διαμάντι', 'Diamond push-up', 'Χέρια ενωμένα κάτω από το στήθος με αντίχειρες και δείκτες να ακουμπούν, αγκώνες κοντά στα πλευρά καθώς κατεβαίνετε. Εκπνεύστε στο σπρώξιμο και κρατήστε το σώμα σφιχτό.', 'Hands together under the chest with thumbs and index fingers touching, elbows brushing the ribs as you lower. Exhale on the push and keep the body rigid.', 'calisthenics', 'intermediate', array['triceps','chest','core']::text[], null, null),
  ('a6c5c9ce-d452-8bcc-0d4c-93d069deed5c'::uuid, 'downward-dog', 'Σκύλος που κοιτά κάτω', 'Downward dog', 'Από τα τέσσερα σηκώστε τους γοφούς πάνω και πίσω σε ανάποδο V, φέρνοντας εναλλάξ τις φτέρνες προς το πάτωμα. Σπρώξτε το πάτωμα με τις παλάμες και αναπνέετε αργά.', 'From all fours lift the hips up and back into an inverted V, pedalling the heels toward the floor one at a time. Press the floor away through the hands and breathe slowly.', 'mobility', 'intermediate', array['hamstrings','calves','shoulders','back']::text[], 'Στρώμα', 'Mat'),
  ('3e29dcb4-724a-190a-9d77-72d7c630ff09'::uuid, 'drill-catch-up-freestyle', 'Άσκηση catch-up στο ελεύθερο', 'Catch-up freestyle drill', 'Κρατήστε το ένα χέρι τεντωμένο μπροστά μέχρι το άλλο να ολοκληρώσει τη χεριά και να το ακουμπήσει, μετά αλλάξτε. Εστιάστε σε μακριά γραμμή σώματος και σταθερή ποδιά· αναπνεύστε στο πλάι χωρίς να σηκώνετε το κεφάλι.', 'Keep one arm extended in front until the other arm finishes its stroke and touches it, then switch. Focus on a long body line and a steady kick; breathe to the side without lifting the head.', 'swimming', 'intermediate', array['shoulders','back','core']::text[], null, null),
  ('a211e795-996b-1049-4889-56585bb88b31'::uuid, 'drill-kick-board', 'Ποδιά με σανίδα', 'Kickboard flutter kick', 'Κρατήστε τη σανίδα με τεντωμένα χέρια, κλωτσήστε από τους γοφούς με χαλαρά γόνατα και τεντωμένα δάχτυλα, κάνοντας μικρό πιτσίλισμα. Κεφάλι χαμηλά και ελεύθερη αναπνοή.', 'Hold the board at arm’s length, kick from the hips with soft knees and pointed toes, making a small splash. Keep the head low and breathe freely.', 'swimming', 'beginner', array['quads','glutes','core']::text[], 'Σανίδα κολύμβησης', 'Kickboard'),
  ('bf812aa0-aacf-1bc1-b63d-de87972024dc'::uuid, 'drill-sculling', 'Άσκηση sculling', 'Sculling drill', 'Επιπλεύστε μπρούμυτα με τα χέρια τεντωμένα και κινήστε τις παλάμες σε μικρά οκτάρια για να νιώσετε πίεση στους πήχεις, προωθούμενοι αργά. Αναπνεύστε με αναπνευστήρα ή σηκωθείτε σύντομα.', 'Float face down with the arms extended and move the hands in small figure-eights to feel pressure on the forearms, propelling slowly forward. Breathe with a snorkel or lift briefly.', 'swimming', 'advanced', array['forearms','shoulders','core']::text[], null, null),
  ('f8ed9b5c-949a-3e7c-24c4-49c0e6a0dde7'::uuid, 'dumbbell-bench-press', 'Πιέσεις πάγκου με αλτήρες', 'Dumbbell bench press', 'Ξαπλώστε στον πάγκο με τα πέλματα στο πάτωμα, κατεβάστε τους αλτήρες στα πλάγια του στήθους με αγκώνες στις 45 μοίρες και πιέστε προς τα πάνω. Εκπνεύστε στην πίεση.', 'Lie on the bench with feet flat, lower the dumbbells to the sides of the chest with elbows at about 45 degrees and press up to lockout. Exhale on the press.', 'gym', 'intermediate', array['chest','triceps','shoulders']::text[], 'Αλτήρες', 'Dumbbells'),
  ('b1c17f82-ff0c-ec85-095c-fd827ec31c2c'::uuid, 'dumbbell-row-home', 'Κωπηλατική με αλτήρα', 'Dumbbell row', 'Κάμψη από τους γοφούς με ίσια πλάτη, το ένα χέρι σε καρέκλα. Τραβήξτε τον αλτήρα προς τον γοφό με τον αγκώνα κοντά στο σώμα, εκπνέοντας στο τράβηγμα.', 'Hinge at the hips with a flat back, one hand on a chair. Pull the dumbbell to the hip with the elbow close to the body, exhaling on the pull.', 'home', 'intermediate', array['back','biceps']::text[], 'Αλτήρες', 'Dumbbells'),
  ('d9b94eb9-d14c-3cf5-35af-6889dd7f510c'::uuid, 'dumbbell-shoulder-press', 'Πιέσεις ώμων με αλτήρες', 'Dumbbell shoulder press', 'Καθιστοί ή όρθιοι, ξεκινήστε με τους αλτήρες στο ύψος των αυτιών και πιέστε πάνω από το κεφάλι μέχρι τα χέρια να τεντώσουν, χωρίς να καμπουριάζει η μέση. Εκπνεύστε στην πίεση.', 'Seated or standing, start with the dumbbells at ear level and press overhead until the arms are straight without arching the lower back. Exhale on the press.', 'gym', 'beginner', array['shoulders','triceps']::text[], 'Αλτήρες', 'Dumbbells'),
  ('624dc756-63be-5dac-5f20-d1c249d4d346'::uuid, 'easy-jog', 'Χαλαρό τζόκινγκ', 'Easy jog', 'Τρέξτε σε ρυθμό συζήτησης με κοντά, γρήγορα βήματα και χαλαρά χέρια. Αν δεν μπορείτε να μιλήσετε άνετα, επιβραδύνετε· αναπνέετε σε σταθερό ρυθμό.', 'Run at a conversational pace with short, quick steps and relaxed arms. If you cannot speak comfortably, slow down; breathe in a steady rhythm.', 'running', 'beginner', array['cardio','quads','calves']::text[], null, null),
  ('f3334a64-3b38-2195-dffc-48aa7c5c1c2c'::uuid, 'easy-spin', 'Χαλαρό πετάλι', 'Easy spin', 'Κάντε πετάλι σε ελαφριά σχέση και χαλαρό ρυθμό, με απαλή λαβή στο τιμόνι και ώμους κάτω. Αναπνέετε από τη μύτη και αφήστε τα πόδια να ζεσταθούν.', 'Pedal in a light gear at a relaxed cadence, hands soft on the bars and shoulders down. Breathe through the nose and let the legs warm up.', 'cycling', 'beginner', array['cardio','quads']::text[], 'Ποδήλατο', 'Bicycle'),
  ('ae1132df-59f4-be0c-0785-5b12393b77a7'::uuid, 'easy-swim-100m', 'Χαλαρό κολύμπι, 100 μέτρα', 'Easy swim, 100 m', 'Κολυμπήστε όποιο στυλ θέλετε σε χαλαρό ρυθμό, με μακριές και ομαλές κινήσεις, για να ζεσταθούν οι ώμοι και να ηρεμήσει η αναπνοή. Εκπνεύστε μέσα στο νερό, εισπνεύστε γρήγορα όταν γυρίζει το πρόσωπο.', 'Swim any stroke at a relaxed pace, long and smooth, to warm the shoulders and settle the breathing. Exhale into the water, inhale quickly when the face turns.', 'swimming', 'beginner', array['cardio','full-body']::text[], null, null),
  ('15036669-9c9b-012e-30f6-b40e34b2d7b6'::uuid, 'easy-swim-cooldown-200m', 'Χαλαρό κολύμπι αποθεραπείας, 200 μέτρα', 'Easy swim cool-down, 200 m', 'Κολυμπήστε αργά εναλλάσσοντας στυλ, επιμηκύνοντας κάθε χεριά και αφήνοντας τον καρδιακό ρυθμό να πέσει. Εκπνεύστε μακριά και αργά μέσα στο νερό.', 'Swim slowly mixing strokes, stretching each stroke out and letting the heart rate drop. Exhale long and slow into the water.', 'swimming', 'intermediate', array['cardio','full-body']::text[], null, null),
  ('5d5d05a0-63f5-e5ba-4b64-fadb1acd31f4'::uuid, 'fartlek-30-30', 'Fartlek 30/30', 'Fartlek 30/30', 'Εναλλάξτε 30 δευτερόλεπτα γρηγορότερου τρεξίματος με 30 δευτερόλεπτα χαλαρού τζόκινγκ, με το αίσθημα και όχι με το ρολόι. Μείνετε χαλαροί στους ώμους και αναπνέετε στα δύσκολα μισά.', 'Alternate 30 seconds of faster running with 30 seconds of easy jogging, by feel rather than by pace. Stay relaxed in the shoulders and breathe through the hard halves.', 'running', 'intermediate', array['cardio','quads','calves']::text[], null, null),
  ('9187fe55-2624-c9e8-d039-6ae5ff23ca22'::uuid, 'fins-kick-set', 'Σετ ποδιάς με βατραχοπέδιλα', 'Kick set with fins', 'Κλωτσήστε μπρούμυτα ή στο πλάι με βατραχοπέδιλα, κινώντας από τους γοφούς με χαλαρό αστράγαλο και σφιχτό κορμό. Κρατήστε στενή ποδιά και ήρεμη αναπνοή.', 'Kick on your front or side with fins, driving from the hips with a loose ankle and a tight core. Keep the kicks narrow and breathe calmly.', 'swimming', 'intermediate', array['quads','glutes','core','cardio']::text[], 'Βατραχοπέδιλα', 'Fins'),
  ('f07f2133-6e54-923e-b4cc-5908301ff79f'::uuid, 'foam-roll-quads', 'Κύλινδρος στους τετρακέφαλους', 'Foam roll quads', 'Ξαπλώστε μπρούμυτα με τον κύλινδρο κάτω από τους μηρούς και κυλήστε αργά από τον γοφό ως το γόνατο, σταματώντας στα ευαίσθητα σημεία. Αναπνέετε αργά και κρατήστε τον κορμό σφιχτό.', 'Lie face down with the roller under the thighs and roll slowly from hip to knee, pausing on tender spots. Breathe slowly and keep the core braced.', 'gym', 'advanced', array['quads','hip-flexors']::text[], 'Αφρώδης κύλινδρος', 'Foam roller'),
  ('64e6d49c-9948-8435-cbc9-316111b34ee8'::uuid, 'freestyle-100m-intervals', 'Ελεύθερο, διαλείμματα 100 μέτρων', 'Freestyle, 100 m intervals', 'Κολυμπήστε 100 μέτρα σε σκληρό αλλά επαναλήψιμο ρυθμό, ξεκινώντας σε σταθερό διάστημα που αφήνει 15–20 δευτερόλεπτα ανάπαυση. Κρατήστε μακριά χεριά στην κούραση και εκπνεύστε πλήρως σε κάθε χεριά.', 'Swim 100 m at a hard but repeatable pace, leaving on a fixed interval that gives 15–20 seconds of rest. Keep the stroke long under fatigue and exhale fully every stroke.', 'swimming', 'advanced', array['cardio','back','shoulders','core']::text[], null, null),
  ('2fa83bc8-3674-d898-8cba-b5c1abb155c9'::uuid, 'freestyle-25m-repeats', 'Ελεύθερο, επαναλήψεις 25 μέτρων', 'Freestyle, 25 m repeats', 'Κολυμπήστε ένα μήκος ελεύθερο με μακριές χεριές, ξεκουραστείτε 20–30 δευτερόλεπτα στον τοίχο, επαναλάβετε. Αναπνέετε κάθε δεύτερη ή τρίτη χεριά και εκπνεύστε πλήρως κάτω από το νερό.', 'Swim one length of freestyle with long strokes, rest 20–30 seconds at the wall, repeat. Breathe every second or third stroke and exhale fully underwater.', 'swimming', 'beginner', array['cardio','back','shoulders']::text[], null, null),
  ('38f811ad-fb30-c988-b381-ca22b1dd8355'::uuid, 'freestyle-50m-repeats', 'Ελεύθερο, επαναλήψεις 50 μέτρων', 'Freestyle, 50 m repeats', 'Κολυμπήστε 50 μέτρα σε σταθερή προσπάθεια που μπορείτε να επαναλάβετε οκτώ φορές, με 20 δευτερόλεπτα ανάπαυση. Κρατήστε σταθερό αριθμό χεριών ανά μήκος και αναπνέετε αμφίπλευρα αν μπορείτε.', 'Swim 50 m at a steady effort you could repeat eight times, resting 20 seconds between. Hold your stroke count per length and breathe bilaterally if you can.', 'swimming', 'intermediate', array['cardio','back','shoulders']::text[], null, null),
  ('830cb125-2101-7df3-2536-afda5df4539a'::uuid, 'german-hang-stretch', 'Διάταση ώμων σε έκταση στο μονόζυγο', 'Shoulder extension stretch on the bar', 'Κρατήστε χαμηλή μπάρα πίσω σας και κατεβάστε απαλά τους γοφούς για να ανοίξει το μπροστινό μέρος των ώμων. Αναπνέετε αργά, κρατήστε τους αγκώνες τεντωμένους και μην πιέζετε ποτέ το εύρος.', 'Hold a low bar behind you and gently lower the hips to open the front of the shoulders. Breathe slowly, keep the elbows straight and never force the range.', 'calisthenics', 'advanced', array['shoulders','chest','biceps']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('929cbac7-a0bf-3842-0a5e-38f9bf36bdf0'::uuid, 'glute-bridge', 'Γέφυρα γλουτών', 'Glute bridge', 'Ξαπλώστε ανάσκελα με λυγισμένα γόνατα, πιέστε με τις φτέρνες και σηκώστε τους γοφούς ώστε το σώμα να σχηματίζει ευθεία από γόνατα έως ώμους. Σφίξτε τους γλουτούς στην κορυφή και εκπνεύστε.', 'Lie on your back with knees bent, press through the heels and lift the hips until the body forms a line from knees to shoulders. Squeeze the glutes at the top and exhale.', 'home', 'beginner', array['glutes','hamstrings','core']::text[], null, null),
  ('abeb4a16-9d35-d3dd-04da-7218ce5de02b'::uuid, 'goblet-squat', 'Goblet squat', 'Goblet squat', 'Κρατήστε αλτήρα ή kettlebell στο στήθος, καθίστε ανάμεσα στα γόνατα με τους αγκώνες μέσα από τους μηρούς και το στήθος ψηλά. Εισπνοή στην κάθοδο, εκπνοή στην άνοδο.', 'Hold a dumbbell or kettlebell at the chest, squat between the knees with the elbows inside the thighs and the chest tall. Inhale down, exhale up.', 'gym', 'intermediate', array['quads','glutes','core']::text[], 'Αλτήρες', 'Dumbbells'),
  ('34da27ee-5f71-4b18-61fd-8c3d8dcd60b8'::uuid, 'half-kneeling-adductor-rock', 'Διάταση προσαγωγών σε γονάτισμα', 'Half-kneeling adductor rock', 'Γονατίστε στο ένα γόνατο με το άλλο πόδι τεντωμένο στο πλάι και το πέλμα στο πάτωμα, και κουνήστε τους γοφούς πίσω προς τη φτέρνα. Εκπνεύστε καθώς πηγαίνετε πίσω· πλάτη ίσια.', 'Kneel on one knee with the other leg extended straight to the side, foot flat, and rock the hips back toward the kneeling heel. Exhale as you rock back; keep the back flat.', 'mobility', 'intermediate', array['adductors','hip-flexors']::text[], 'Στρώμα', 'Mat'),
  ('1e167e11-c464-7b5d-9fa5-b18f7c2f8e87'::uuid, 'hanging-knee-raise', 'Άρσεις γονάτων σε κρέμασμα', 'Hanging knee raise', 'Κρεμαστείτε από τη μπάρα και σηκώστε τα γόνατα προς το στήθος γυρίζοντας τη λεκάνη, μετά κατεβάστε αργά χωρίς αιώρηση. Εκπνεύστε καθώς ανεβαίνουν τα γόνατα.', 'Hang from the bar and lift the knees toward the chest by curling the pelvis, then lower slowly without swinging. Exhale as the knees rise.', 'calisthenics', 'intermediate', array['core','hip-flexors','forearms']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('98223cbf-3fe5-6b51-ddbe-82b5f1eba83c'::uuid, 'hanging-leg-raise', 'Άρσεις ποδιών σε κρέμασμα', 'Hanging leg raise', 'Κρεμαστείτε με τεντωμένα χέρια και σηκώστε τεντωμένα πόδια στο ύψος των γοφών ή ψηλότερα γυρίζοντας τη λεκάνη. Εκπνεύστε στην άρση και κατεβάστε αργά χωρίς αιώρηση.', 'Hang with straight arms and lift straight legs to hip height or higher by curling the pelvis up. Exhale on the lift and lower slowly without swinging.', 'calisthenics', 'advanced', array['core','hip-flexors','forearms']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('3e49a210-bc10-f895-8f31-fc42fec3b18a'::uuid, 'high-knees', 'Ψηλά γόνατα', 'High knees', 'Τρέξτε επί τόπου φέρνοντας τα γόνατα στο ύψος των γοφών με γρήγορη επαφή στο έδαφος και όρθια στάση. Κουνάτε τα χέρια και κρατήστε την αναπνοή γρήγορη αλλά χαλαρή.', 'Jog in place driving the knees to hip height with a quick ground contact and tall posture. Keep the arms pumping and the breath quick but relaxed.', 'running', 'beginner', array['hip-flexors','cardio','calves']::text[], null, null),
  ('85e90a55-f913-5b8a-dcf0-faf8297dccf1'::uuid, 'hill-sprints', 'Σπριντ σε ανηφόρα, 10–12 δευτερόλεπτα', 'Hill sprints, 10–12 s', 'Σπριντάρετε δυνατά σε μέτρια ανηφόρα για 10–12 δευτερόλεπτα, σπρώχνοντας γόνατα και χέρια, μετά κατεβείτε περπατώντας για πλήρη αποκατάσταση. Εκπνεύστε δυνατά σε κάθε ώθηση.', 'Sprint hard up a moderate hill for 10–12 seconds, driving the knees and arms, then walk down for full recovery. Exhale forcefully with each push-off.', 'running', 'advanced', array['glutes','quads','calves','cardio']::text[], null, null),
  ('42b48d9c-e62b-0d5a-a8e5-638c8a1357f1'::uuid, 'hill-walk-recovery', 'Ανηφορικό περπάτημα αποκατάστασης', 'Hill walk recovery', 'Περπατήστε ήπια ανηφόρα με κοντά βήματα και ελαφριά κλίση μπροστά, μετά κατεβείτε χαλαρά. Χρησιμοποιήστε την ανηφόρα για να ελέγξετε ξανά την αναπνοή.', 'Walk up a gentle hill with short steps and a slight forward lean, then jog or walk down easy. Use the climb to bring the breathing back under control.', 'running', 'intermediate', array['cardio','glutes','calves']::text[], null, null),
  ('cca7fa5a-0458-e19e-f671-4d706a8f15da'::uuid, 'hip-circles', 'Κύκλοι ισχίων', 'Hip circles', 'Χέρια στους γοφούς, κάντε αργούς πλατιούς κύκλους με τη λεκάνη προς τις δύο κατευθύνσεις σαν να γυρίζετε χούλα χουπ. Γόνατα χαλαρά και άνετη αναπνοή.', 'Hands on the hips, draw slow wide circles with the pelvis in both directions as if tracing a hula hoop. Keep the knees soft and breathe easily.', 'mobility', 'beginner', array['hip-flexors','glutes']::text[], null, null),
  ('70821074-c07f-a3c2-3d17-6411e0a8213f'::uuid, 'hip-flexor-stretch-kneeling', 'Διάταση καμπτήρων ισχίου σε γονάτισμα', 'Kneeling hip flexor stretch', 'Γονατίστε στο ένα πόδι, γείρετε τη λεκάνη και μετακινηθείτε απαλά μπροστά μέχρι να τεντώσει το μπροστινό μέρος του πίσω ισχίου, κορμός όρθιος. Αναπνέετε αργά και κρατήστε 30–45 δευτερόλεπτα ανά πλευρά.', 'Half-kneel, tuck the pelvis and shift forward gently until the front of the back hip stretches, torso tall. Breathe slowly and hold 30–45 seconds each side.', 'running', 'advanced', array['hip-flexors','quads']::text[], 'Στρώμα', 'Mat'),
  ('3b128f8a-1188-640a-8b40-fbb73f3c21e9'::uuid, 'hollow-hold', 'Hollow hold', 'Hollow body hold', 'Μέση πιεσμένη στο πάτωμα, χέρια πάνω από το κεφάλι και πόδια τεντωμένα λίγα εκατοστά από το έδαφος, σώμα σε σχήμα ρηχής μπανάνας. Αναπνέετε σταθερά σε όλη τη διάρκεια.', 'Lower back pressed into the floor, arms overhead and legs straight a few centimetres off the ground, body shaped like a shallow banana. Breathe steadily throughout.', 'calisthenics', 'intermediate', array['core','hip-flexors']::text[], null, null),
  ('6df9c70b-20e5-53c8-63e9-cd671b397e41'::uuid, 'hollow-hold-tuck', 'Hollow hold με μαζεμένα γόνατα', 'Tuck hollow hold', 'Ξαπλώστε ανάσκελα, πιέστε τη μέση στο πάτωμα και σηκώστε ώμους και λυγισμένα γόνατα από το έδαφος. Αναπνέετε σταθερά χωρίς να σηκώνεται η μέση.', 'Lie on your back, press the lower back into the floor and lift the shoulders and bent knees off the ground. Breathe steadily without letting the back arch.', 'calisthenics', 'beginner', array['core','hip-flexors']::text[], null, null),
  ('d3fd05a3-05e3-8e86-563d-590b4af4381a'::uuid, 'hypoxic-breathing-set', 'Σετ μοτίβου αναπνοής (3-5-7)', 'Breathing-pattern set (3-5-7)', 'Κολυμπήστε 25 μέτρα αναπνέοντας κάθε 3η χεριά, μετά κάθε 5η, μετά κάθε 7η, με ανάπαυση ανάμεσα. Σταματήστε και αναπνεύστε κανονικά μόλις νιώσετε ζάλη· ποτέ μόνοι σας σε αυτό.', 'Swim 25 m breathing every 3rd stroke, then every 5th, then every 7th, with rest between. Stop and breathe normally the moment you feel light-headed; never swim alone for this.', 'swimming', 'advanced', array['cardio','core']::text[], null, null),
  ('f14a6d70-8707-c506-5c04-69c5c7522cba'::uuid, 'incline-push-up', 'Κάμψεις με κλίση', 'Incline push-up', 'Χέρια σε πάγκο ή σκαλί, σώμα ευθεία από το κεφάλι ως τις φτέρνες, κατεβάστε το στήθος στην άκρη και σπρώξτε. Εκπνεύστε στο σπρώξιμο· όσο χαμηλότερη η επιφάνεια, τόσο δυσκολότερο.', 'Hands on a bench or step, body straight from head to heels, lower the chest to the edge and press away. Exhale on the push; a lower surface makes it harder.', 'calisthenics', 'beginner', array['chest','triceps','shoulders']::text[], null, null),
  ('0cbe8825-ccf2-a8a1-fe21-5cfcc4cf4212'::uuid, 'individual-medley-100m', 'Μικτή ατομική, 100 μέτρα', 'Individual medley, 100 m', 'Κολυμπήστε 25 μέτρα από πεταλούδα, ύπτιο, πρόσθιο και ελεύθερο με κανονικές στροφές ανάμεσα. Μοιράστε την προσπάθεια στο πρώτο μισό και αναπνέετε συνειδητά σε κάθε στυλ.', 'Swim 25 m each of butterfly, backstroke, breaststroke and freestyle with legal turns between. Pace the first half and breathe deliberately in every stroke.', 'swimming', 'advanced', array['full-body','cardio']::text[], null, null),
  ('7257226f-a14b-2e43-d217-2bab2207551a'::uuid, 'intervals-400m', 'Διαλείμματα 400 μέτρων', 'Intervals, 400 m', 'Τρέξτε 400 μέτρα περίπου στον ρυθμό αγώνα 5 χιλιομέτρων, μετά τζόκινγκ ή περπάτημα για ίσο χρόνο· επαναλάβετε. Κρατήστε όρθια τεχνική όταν δυσκολεύει και αναπνέετε βαθιά, όχι με λαχάνιασμα.', 'Run 400 m at roughly your 5 km race pace, then jog or walk for equal time to recover; repeat. Keep the form tall when it hurts and breathe deeply, not in gasps.', 'running', 'advanced', array['cardio','quads','hamstrings','calves']::text[], null, null),
  ('d12f0bc9-c641-8d58-8253-b9f4475673ed'::uuid, 'jefferson-curl', 'Jefferson curl (ελαφρύ)', 'Jefferson curl (light)', 'Όρθιοι σε σκαλί με πολύ ελαφρύ βάρος, μαζέψτε το πηγούνι και κυλήστε κάτω σπόνδυλο-σπόνδυλο μέχρι το βάρος να περάσει τα δάχτυλα, μετά ξαναχτίστε προς τα πάνω. Εκπνεύστε στην κάθοδο· μην αυξάνετε ποτέ γρήγορα το βάρος.', 'Standing on a step with a very light weight, tuck the chin and roll down one vertebra at a time until the weight passes the toes, then stack back up. Exhale on the way down; never add load quickly.', 'mobility', 'advanced', array['hamstrings','back']::text[], 'Αλτήρες', 'Dumbbells'),
  ('09b819ec-c747-f210-306a-48f026500091'::uuid, 'jump-squat', 'Καθίσματα με άλμα', 'Jump squat', 'Καθίστε και εκραγείτε προς τα πάνω, προσγειωθείτε αθόρυβα πίσω στο κάθισμα με τα γόνατα στην κατεύθυνση των δακτύλων. Εκπνεύστε στο άλμα.', 'Squat down, then explode upward and land quietly back into the squat with knees tracking over the toes. Exhale on the jump.', 'home', 'advanced', array['quads','glutes','calves','cardio']::text[], null, null),
  ('ff843438-0342-2ecb-2c0d-9ce40fac2dc3'::uuid, 'jumping-jacks', 'Jumping jacks', 'Jumping jacks', 'Ανοίξτε τα πόδια με άλμα ενώ τα χέρια ανεβαίνουν πάνω από το κεφάλι, και κλείστε ξανά. Προσγειωθείτε απαλά στις μύτες και κρατήστε ρυθμική αναπνοή.', 'Jump the feet wide while the arms rise overhead, then back together. Land softly on the balls of the feet and keep the breath rhythmic.', 'home', 'intermediate', array['cardio','full-body']::text[], null, null),
  ('85f13e16-9cab-cc1b-dbac-14fadb44b80a'::uuid, 'kettlebell-swing', 'Αιωρήσεις με kettlebell', 'Kettlebell swing', 'Κάμψη από τους γοφούς, στείλτε το kettlebell πίσω και σπρώξτε απότομα τους γοφούς μπροστά ώστε να ανέβει στο ύψος του στήθους με τεντωμένα χέρια. Εκπνεύστε απότομα στην κορυφή· τα χέρια μόνο καθοδηγούν.', 'Hinge at the hips, hike the bell back and snap the hips forward so it floats to chest height with straight arms. Exhale sharply at the top; the arms only guide.', 'gym', 'advanced', array['glutes','hamstrings','core','cardio']::text[], 'Kettlebell', 'Kettlebell'),
  ('dccb01c5-16fd-87f7-d221-3f6ba774faa4'::uuid, 'knee-plank', 'Σανίδα στα γόνατα', 'Knee plank', 'Πήχεις κάτω από τους ώμους, γόνατα στο πάτωμα, ευθεία γραμμή από το κεφάλι ως τα γόνατα. Σφίξτε την κοιλιά και αναπνέετε σταθερά.', 'Forearms under the shoulders, knees on the floor, straight line from head to knees. Brace the belly as if expecting a tap and breathe steadily.', 'home', 'beginner', array['core','shoulders']::text[], null, null),
  ('b86c23e7-69d3-1048-0ece-a933deea010a'::uuid, 'l-sit', 'L-sit', 'L-sit', 'Στηριχθείτε σε δίζυγο ή στο πάτωμα με τεντωμένα χέρια, σηκώστε τα τεντωμένα πόδια σε οριζόντια θέση και κρατήστε με τους ώμους πιεσμένους κάτω. Αναπνέετε κοντά και σταθερά· λυγίστε τα γόνατα για ευκολότερη εκδοχή.', 'Support on dip bars or the floor with straight arms, lift straight legs to horizontal and hold with the shoulders pushed down. Breathe short and steady; bend the knees to regress.', 'calisthenics', 'advanced', array['core','hip-flexors','triceps']::text[], 'Δίζυγο', 'Dip bars'),
  ('34db6a1f-0062-958e-8ec5-aaae82435f80'::uuid, 'lat-pulldown', 'Έλξεις τροχαλίας', 'Lat pulldown', 'Λαβή λίγο πιο ανοιχτή από τους ώμους, γείρετε ελαφρά πίσω και τραβήξτε τη μπάρα στο πάνω στήθος με τους αγκώνες να κατεβαίνουν. Εκπνεύστε στο τράβηγμα και ελέγξτε την επιστροφή.', 'Grip slightly wider than the shoulders, lean back a little and pull the bar to the upper chest while the elbows drive down. Exhale on the pull and control the return.', 'gym', 'beginner', array['back','biceps']::text[], 'Τροχαλία', 'Cable machine'),
  ('cc19715c-2be0-7c11-09e7-0b2acf486ac9'::uuid, 'lat-stretch-bar', 'Διάταση πλάτης στο μονόζυγο', 'Lat stretch on the bar', 'Κρατήστε τη μπάρα με το ένα χέρι και στείλτε τους γοφούς πίσω και μακριά για να επιμηκυνθεί η πλευρά της πλάτης. Αναπνέετε αργά και κρατήστε 30 δευτερόλεπτα σε κάθε πλευρά.', 'Hold the bar with one hand and sit the hips back and away to lengthen the side of the back. Breathe slowly and hold 30 seconds each side.', 'calisthenics', 'intermediate', array['back','shoulders']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('1095f840-9e6b-b768-de25-9029e42b62ab'::uuid, 'leg-press', 'Πιέσεις ποδιών', 'Leg press', 'Πόδια στο άνοιγμα των ώμων πάνω στην πλατφόρμα, κατεβάστε μέχρι τα γόνατα να φτάσουν περίπου στις 90 μοίρες χωρίς να σηκωθεί η μέση. Εκπνεύστε καθώς σπρώχνετε, μην κλειδώνετε τα γόνατα.', 'Feet shoulder-width on the platform, lower the sled until the knees reach about 90 degrees without the lower back lifting off the pad. Exhale as you press, never lock the knees.', 'gym', 'beginner', array['quads','glutes','hamstrings']::text[], 'Μηχάνημα', 'Machine'),
  ('61b54470-3c60-ec01-c7c5-cec84ac8a87b'::uuid, 'leg-swings', 'Αιωρήσεις ποδιών', 'Leg swings', 'Κρατηθείτε από τοίχο και αιωρήστε το ένα πόδι μπρος-πίσω, μετά πλάγια, αυξάνοντας το εύρος σταδιακά. Κορμός ψηλά και άνετη αναπνοή· 10–15 ανά κατεύθυνση.', 'Hold a wall and swing one leg forward and back, then side to side, growing the range gradually. Keep the torso tall and breathe easily; 10–15 each direction.', 'running', 'beginner', array['hip-flexors','hamstrings','adductors']::text[], null, null),
  ('23f2b890-d426-c531-b78d-77767a517697'::uuid, 'legs-up-the-wall', 'Πόδια στον τοίχο', 'Legs up the wall', 'Ξαπλώστε ανάσκελα με τους γοφούς κοντά σε τοίχο και τα πόδια τεντωμένα πάνω του, χέρια χαλαρά στα πλάγια. Αναπνέετε αργά και βαθιά για 2–5 λεπτά ως αποθεραπεία όλου του σώματος.', 'Lie on your back with the hips near a wall and the legs resting straight up it, arms relaxed at the sides. Breathe slowly and deeply for 2–5 minutes as a full-body cool-down.', 'mobility', 'advanced', array['hamstrings','back']::text[], 'Στρώμα', 'Mat'),
  ('d2513590-6ccd-c55a-d496-d61233cc3d2a'::uuid, 'long-endurance-ride', 'Μεγάλη διαδρομή αντοχής', 'Long endurance ride', 'Οδηγήστε δύο ώρες ή περισσότερο σε σταθερό ρυθμό συζήτησης, τρώγοντας και πίνοντας κάθε 20–30 λεπτά. Αλλάζετε συχνά θέση χεριών και κρατήστε χαλαρή αναπνοή.', 'Ride for two hours or more at a steady conversational pace, eating and drinking every 20–30 minutes. Change hand position often and keep the breathing relaxed.', 'cycling', 'advanced', array['cardio','quads','glutes']::text[], 'Ποδήλατο', 'Bicycle'),
  ('90659ff6-50d3-f2d7-89c9-c719548a0b5b'::uuid, 'long-run-easy', 'Μεγάλη χαλαρή διαδρομή', 'Long easy run', 'Τρέξτε σε χαλαρό ρυθμό συζήτησης για περισσότερο από το συνηθισμένο, με κοντά και ελαφριά βήματα. Πιείτε νερό όσο χρειάζεται και κρατήστε χαλαρή αναπνοή σε όλη τη διάρκεια.', 'Run at an easy, conversational pace for longer than your usual run, keeping the steps short and light. Drink as needed and keep the breathing relaxed throughout.', 'running', 'advanced', array['cardio','quads','hamstrings','calves']::text[], null, null),
  ('782bda36-33b8-c74e-f3dd-377e82e63ae4'::uuid, 'low-cadence-strength', 'Προσπάθειες δύναμης με χαμηλό ρυθμό', 'Low-cadence strength efforts', 'Καθιστοί σε βαριά σχέση στις 50–60 στροφές, σπρώξτε δυνατή και ομαλή προσπάθεια για 5 λεπτά με σφιχτό κορμό και γόνατα σε ευθεία. Αναπνέετε αργά· σταματήστε αν πονέσουν τα γόνατα.', 'Seated in a heavy gear at 50–60 rpm, push a strong, smooth effort for 5 minutes with the core braced and the knees tracking straight. Breathe slowly; stop if the knees complain.', 'cycling', 'advanced', array['quads','glutes','hamstrings']::text[], 'Ποδήλατο', 'Bicycle'),
  ('0b828bb0-4c76-7897-d71f-4a7fa748fe1b'::uuid, 'march-in-place', 'Βάδισμα επί τόπου', 'March in place', 'Σηκώνετε τα γόνατα στο ύψος του ισχίου και κουνάτε τα χέρια φυσικά. Κρατήστε σταθερό ρυθμό και αναπνέετε από τη μύτη.', 'Lift the knees to hip height and swing the arms naturally. Keep a steady rhythm and breathe through the nose.', 'home', 'beginner', array['cardio','hip-flexors']::text[], null, null),
  ('bcd1566a-b40e-5a4c-cf59-da4d1b25b261'::uuid, 'mountain-climbers', 'Ορειβάτες', 'Mountain climbers', 'Από ψηλή σανίδα, φέρτε το ένα γόνατο προς το στήθος και εναλλάξτε γρήγορα, κρατώντας τους γοφούς σταθερούς. Ώμοι πάνω από τους καρπούς και γρήγορη αλλά σταθερή αναπνοή.', 'From a high plank, drive one knee toward the chest and switch quickly while the hips stay level. Keep the shoulders over the wrists and breathe fast but steady.', 'home', 'intermediate', array['core','cardio','hip-flexors']::text[], null, null),
  ('09f6d56b-353a-8732-7843-1841747a5c48'::uuid, 'neck-rolls', 'Κύκλοι αυχένα', 'Neck rolls', 'Κατεβάστε το πηγούνι στο στήθος και γυρίστε το κεφάλι αργά από ώμο σε ώμο σε ημικύκλιο, χωρίς να πιέζετε προς τα πίσω. Αναπνέετε αργά σε κάθε πέρασμα.', 'Drop the chin to the chest and roll the head slowly from shoulder to shoulder in a half circle, never forcing backward. Breathe slowly with each pass.', 'mobility', 'beginner', array['shoulders']::text[], null, null),
  ('6265e8b1-2ea1-96b2-24f1-4ad5d518bff6'::uuid, 'ninety-ninety-hip-switch', 'Εναλλαγή ισχίων 90/90', '90/90 hip switch', 'Καθίστε με τα δύο γόνατα λυγισμένα στις 90 μοίρες, το ένα μπροστά και το άλλο στο πλάι, και γυρίστε τα γόνατα προς την άλλη πλευρά χωρίς τα χέρια. Καθίστε όρθιοι και εκπνεύστε στην αλλαγή.', 'Sit with both knees bent at 90 degrees, one in front and one to the side, then rotate the knees to the other side without using the hands. Sit tall and exhale on the switch.', 'mobility', 'intermediate', array['hip-flexors','glutes','adductors']::text[], 'Στρώμα', 'Mat'),
  ('b611331f-2a1d-3740-9b34-d27c43fbad6a'::uuid, 'over-under-intervals', 'Διαλείμματα over-under', 'Over-under intervals', 'Εναλλάξτε 2 λεπτά λίγο κάτω από τον σκληρό βιώσιμο ρυθμό σας με 1 λεπτό λίγο πάνω, για 9–12 λεπτά. Κρατήστε σταθερό ρυθμό πεταλιάς και αναπνέετε στο δύσκολο λεπτό.', 'Alternate 2 minutes just below your hard sustainable pace with 1 minute just above it, for 9–12 minutes. Keep the cadence steady and breathe through the harder minute.', 'cycling', 'intermediate', array['cardio','quads','glutes']::text[], 'Ποδήλατο', 'Bicycle'),
  ('ab6bcfc9-bfc9-7ebf-8507-af38ac2ced5d'::uuid, 'overhead-press', 'Πιέσεις ώμων με μπάρα', 'Barbell overhead press', 'Μπάρα στις κλείδες, σφίξτε γλουτούς και κορμό, πιέστε κάθετα και περάστε το κεφάλι μπροστά μόλις περάσει η μπάρα. Εκπνεύστε στην πίεση, κατεβάστε ελεγχόμενα.', 'Bar at the collarbones, squeeze the glutes and brace, press straight up and move the head through once the bar passes. Exhale on the press, lower with control.', 'gym', 'advanced', array['shoulders','triceps','core']::text[], 'Μπάρα', 'Barbell'),
  ('47e73959-7343-b543-d74c-ec99a9f9676c'::uuid, 'parallel-bar-dip', 'Βυθίσεις στο δίζυγο', 'Parallel bar dip', 'Στηριχθείτε στις μπάρες με τεντωμένα χέρια, γείρετε ελαφρά μπροστά και κατεβείτε μέχρι οι ώμοι να περάσουν λίγο κάτω από τους αγκώνες. Εκπνεύστε καθώς σπρώχνετε· σταματήστε πριν τσιμπήσει ο ώμος.', 'Support on the bars with straight arms, lean slightly forward and lower until the shoulders dip just below the elbows. Exhale as you press up; stop short of any shoulder pinch.', 'calisthenics', 'advanced', array['chest','triceps','shoulders']::text[], 'Δίζυγο', 'Dip bars'),
  ('d18b7793-86a7-d59c-6956-c852b048834e'::uuid, 'pigeon-stretch', 'Διάταση περιστεριού', 'Pigeon stretch', 'Από τα τέσσερα φέρτε την κνήμη μπροστά διαγώνια και τεντώστε το άλλο πόδι πίσω, γοφοί ευθυγραμμισμένοι. Σκύψτε μόνο όσο η αναπνοή μένει αργή· κρατήστε 30–45 δευτερόλεπτα σε κάθε πλευρά.', 'From all fours bring one shin forward across the body and extend the other leg back, hips square. Fold forward only as far as the breath stays slow; hold 30–45 seconds each side.', 'home', 'advanced', array['glutes','hip-flexors']::text[], null, null),
  ('6411c7a5-98ab-64c4-ac41-f900117c4892'::uuid, 'pistol-squat', 'Καθίσματα σε ένα πόδι (pistol)', 'Pistol squat', 'Σταθείτε σε ένα πόδι με το άλλο τεντωμένο μπροστά, καθίστε αργά κρατώντας τη φτέρνα στο πάτωμα και τα χέρια μπροστά για ισορροπία. Εκπνεύστε καθώς σηκώνεστε· κρατηθείτε αν χρειάζεται.', 'Stand on one leg with the other extended forward, sit down slowly keeping the heel on the floor and the arms reaching forward for balance. Exhale as you stand; hold a support if needed.', 'calisthenics', 'advanced', array['quads','glutes','core']::text[], null, null),
  ('0dfffe17-2938-b20f-2ea6-302031842075'::uuid, 'plank', 'Σανίδα', 'Plank', 'Πήχεις στο πάτωμα, μύτες ποδιών στο έδαφος, σώμα σε ευθεία γραμμή. Σφίξτε τους γλουτούς, κατεβάστε τα πλευρά και αναπνέετε χωρίς να πέφτουν οι γοφοί.', 'Forearms on the floor, toes tucked, body a straight line. Squeeze the glutes, pull the ribs down and breathe without letting the hips sag.', 'home', 'intermediate', array['core','shoulders']::text[], null, null),
  ('9036ff65-2f12-0d5a-99e3-29849fcc1dc3'::uuid, 'pool-wall-shoulder-stretch', 'Διάταση ώμων στον τοίχο της πισίνας', 'Shoulder stretch at the pool wall', 'Κρατηθείτε από το χείλος με το ένα χέρι, γυρίστε το σώμα αντίθετα μέχρι να τεντώσει το μπροστινό μέρος του ώμου, μετά αλλάξτε. Αναπνέετε αργά και κρατήστε 20–30 δευτερόλεπτα ανά πλευρά.', 'Hold the gutter with one hand, turn the body away until the front of the shoulder stretches, then switch. Breathe slowly and hold 20–30 seconds each side.', 'swimming', 'beginner', array['shoulders','chest']::text[], null, null),
  ('3f9e14a5-d015-4530-e9fd-0d42018e55c7'::uuid, 'post-ride-foam-roll', 'Κύλινδρος μετά τη διαδρομή', 'Post-ride foam rolling', 'Κυλήστε τετρακέφαλους, γλουτούς και γάμπες αργά για περίπου ένα λεπτό το καθένα, σταματώντας στα σφιγμένα σημεία. Αναπνέετε αργά και κρατήστε την πίεση ανεκτή.', 'Roll the quads, glutes and calves slowly for about a minute each, pausing on tight spots. Breathe slowly and keep the pressure tolerable.', 'cycling', 'advanced', array['quads','glutes','calves']::text[], 'Αφρώδης κύλινδρος', 'Foam roller'),
  ('a05e47f6-2cdc-06aa-976d-17a7bcdc1272'::uuid, 'post-ride-hip-stretch', 'Διάταση ισχίου σε θέση τέσσερα', 'Figure-four hip stretch', 'Καθίστε ή ξαπλώστε, σταυρώστε τον έναν αστράγαλο πάνω από το αντίθετο γόνατο και τραβήξτε τα πόδια προς το στήθος μέχρι να τεντώσει ο έξω γοφός. Αναπνέετε αργά, 30 δευτερόλεπτα ανά πλευρά.', 'Sit or lie down, cross one ankle over the opposite knee and draw the legs toward the chest until the outer hip stretches. Breathe slowly, 30 seconds per side.', 'cycling', 'intermediate', array['glutes','hip-flexors']::text[], 'Στρώμα', 'Mat'),
  ('dc229737-c193-6eb7-9515-394656abc20c'::uuid, 'post-ride-quad-stretch', 'Διάταση τετρακεφάλων μετά τη διαδρομή', 'Post-ride quad stretch', 'Κατεβείτε από το ποδήλατο, κρατηθείτε από το σκελετό ή τοίχο και φέρτε τη μία φτέρνα στους γλουτούς με τα γόνατα ενωμένα και τη λεκάνη μαζεμένη. Αναπνέετε αργά, 30 δευτερόλεπτα ανά πλευρά.', 'Off the bike, hold the frame or a wall and draw one heel to the glutes with the knees together and the pelvis tucked. Breathe slowly, 30 seconds each side.', 'cycling', 'beginner', array['quads','hip-flexors']::text[], null, null),
  ('394a22d6-b529-c1c2-7799-d0d11127f883'::uuid, 'pull-buoy-freestyle', 'Ελεύθερο με pull buoy', 'Pull buoy freestyle', 'Κρατήστε το pull buoy ανάμεσα στους μηρούς και κολυμπήστε ελεύθερο μόνο με τα χέρια, τεντώνοντας μακριά και τραβώντας μέχρι τον γοφό. Εκπνεύστε συνεχόμενα κάτω από το νερό και κρατήστε τους γοφούς ψηλά.', 'Hold the buoy between the thighs and swim freestyle with the arms only, reaching long and pulling through to the hip. Exhale continuously underwater and keep the hips high.', 'swimming', 'intermediate', array['back','shoulders','triceps']::text[], 'Pull buoy', 'Pull buoy'),
  ('537b7015-9eec-eeb6-4b7c-fd813bb3abea'::uuid, 'pull-up', 'Έλξεις στο μονόζυγο', 'Pull-up', 'Λαβή με παλάμες μπροστά, ξεκινήστε από πλήρες κρέμασμα και τραβήξτε μέχρι το πηγούνι να περάσει τη μπάρα με τους αγκώνες να κατεβαίνουν. Εκπνεύστε στο τράβηγμα και κατεβείτε πλήρως.', 'Overhand grip, start from a full hang and pull until the chin passes the bar with the elbows driving down. Exhale on the pull and lower all the way.', 'calisthenics', 'intermediate', array['back','biceps','core']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('bf802b94-aa69-be95-e104-1d4d73f586d2'::uuid, 'push-up', 'Κάμψεις', 'Push-up', 'Χέρια λίγο πιο ανοιχτά από τους ώμους, σώμα σφιχτό από το κεφάλι ως τις φτέρνες. Κατεβάστε το στήθος προς το πάτωμα με αγκώνες στις 45 μοίρες και εκπνεύστε στο σπρώξιμο.', 'Hands slightly wider than the shoulders, body rigid from head to heels. Lower the chest toward the floor with elbows at about 45 degrees and exhale on the push.', 'home', 'intermediate', array['chest','triceps','shoulders','core']::text[], null, null),
  ('52b94d58-4db4-7188-27e2-71ef8fd07409'::uuid, 'reverse-lunge', 'Προβολές προς τα πίσω', 'Reverse lunge', 'Κάντε βήμα πίσω με το ένα πόδι και κατεβείτε μέχρι τα δύο γόνατα να είναι κοντά στις 90 μοίρες, κορμός όρθιος. Σπρώξτε με τη μπροστινή φτέρνα για να επιστρέψετε και εναλλάξτε πόδια.', 'Step one foot back and lower until both knees are near 90 degrees, torso upright. Drive through the front heel to return and alternate legs.', 'home', 'intermediate', array['quads','glutes','hamstrings']::text[], null, null),
  ('4f482741-9c71-3cce-8fa5-7a4cd0c0d925'::uuid, 'romanian-deadlift', 'Ρουμανικές άρσεις θανάτου', 'Romanian deadlift', 'Ελαφρά λυγισμένα γόνατα, σπρώξτε τους γοφούς πίσω και κατεβάστε τη μπάρα κατά μήκος των μηρών με ίσια πλάτη μέχρι να νιώσετε τους οπίσθιους μηριαίους να τεντώνουν. Εκπνεύστε καθώς οι γοφοί σπρώχνουν μπροστά.', 'Soft knees, push the hips back and lower the bar along the thighs with a flat back until you feel the hamstrings stretch. Exhale as the hips drive forward to stand.', 'gym', 'intermediate', array['hamstrings','glutes','back']::text[], 'Μπάρα', 'Barbell'),
  ('eeb634a0-7b33-33f1-b32b-531673576485'::uuid, 'rowing-machine-easy', 'Κωπηλατοεργόμετρο, χαλαρός ρυθμός', 'Rowing machine, easy pace', 'Σπρώξτε πρώτα με τα πόδια, μετά γείρετε τον κορμό και τελειώστε με τα χέρια· αντίστροφη σειρά στην επιστροφή. Κρατήστε χαμηλό ρυθμό κωπηλασίας και εκπνεύστε στην ώθηση.', 'Push with the legs first, then swing the torso and finish with the arms; reverse the order on the return. Keep the stroke rate low and breathe out on the drive.', 'gym', 'intermediate', array['cardio','back','full-body']::text[], 'Μηχάνημα', 'Machine'),
  ('57215046-8d78-c61d-dc55-adaaf26ad550'::uuid, 'scapular-pull-up', 'Έλξεις ωμοπλατών', 'Scapular pull-up', 'Από παθητικό κρέμασμα, τραβήξτε τις ωμοπλάτες κάτω και μαζί ώστε το σώμα να ανέβει λίγα εκατοστά με τεντωμένα χέρια, μετά χαλαρώστε. Εκπνεύστε στο σφίξιμο.', 'From a dead hang, pull the shoulder blades down and together so the body rises a few centimetres with straight arms, then release. Exhale on the squeeze.', 'calisthenics', 'intermediate', array['back','shoulders']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('9da84891-54a1-5010-e7d4-08dd490a4fc5'::uuid, 'seated-cable-row', 'Κωπηλατική τροχαλίας καθιστά', 'Seated cable row', 'Καθίστε όρθιοι με ελαφρά λυγισμένα γόνατα, τραβήξτε τη λαβή στην κοιλιά σφίγγοντας τις ωμοπλάτες. Εκπνεύστε στο τράβηγμα και αφήστε τα χέρια να τεντώσουν στην επιστροφή.', 'Sit tall with a slight knee bend, pull the handle to the belly squeezing the shoulder blades together. Exhale on the pull and let the arms extend fully on the return.', 'gym', 'beginner', array['back','biceps']::text[], 'Τροχαλία', 'Cable machine'),
  ('7a604d68-b9c1-000a-25e2-51fc38db24fd'::uuid, 'seated-climb-intervals', 'Διαλείμματα καθιστής ανάβασης, 5 λεπτά', 'Seated climb intervals, 5 min', 'Βάλτε βαρύτερη σχέση στις 70–80 στροφές και κρατήστε δυνατή καθιστή προσπάθεια για 5 λεπτά, με τα χέρια πάνω στο τιμόνι. Ήρεμος κορμός και ρυθμική αναπνοή· χαλαρό πετάλι ανάμεσα.', 'Shift to a heavier gear at 70–80 rpm and hold a strong seated effort for 5 minutes, hands on the tops. Keep the torso quiet and breathe rhythmically; spin easy between efforts.', 'cycling', 'intermediate', array['quads','glutes','hamstrings','cardio']::text[], 'Ποδήλατο', 'Bicycle'),
  ('90116cb7-ea28-6281-656d-ceb6926a1bb4'::uuid, 'seated-hamstring-stretch', 'Διάταση οπίσθιων μηριαίων καθιστά', 'Seated hamstring stretch', 'Καθίστε με το ένα πόδι τεντωμένο, τεντωθείτε προς τα δάχτυλα με μακριά σπονδυλική στήλη αντί για καμπουριασμένη πλάτη. Εκπνεύστε στη διάταση και κρατήστε 30 δευτερόλεπτα ανά πλευρά.', 'Sit with one leg straight, reach toward the toes with a long spine instead of a rounded back. Exhale into the stretch and hold 30 seconds per side.', 'home', 'intermediate', array['hamstrings','back']::text[], null, null),
  ('e92bd8c2-800d-9a4b-e0cd-322043b9c880'::uuid, 'shoulder-rolls', 'Κύκλοι ώμων', 'Shoulder rolls', 'Σηκώστε τους ώμους προς τα αυτιά, γυρίστε τους πίσω και κάτω σε αργούς κύκλους, μετά αντίστροφα. Εκπνεύστε καθώς πέφτουν οι ώμοι.', 'Lift the shoulders toward the ears, roll them back and down in slow circles, then reverse. Exhale as the shoulders drop.', 'mobility', 'beginner', array['shoulders','back']::text[], null, null),
  ('4844075c-e76c-68d0-9b21-2759aa14a1fa'::uuid, 'single-leg-glute-bridge', 'Γέφυρα γλουτών με ένα πόδι', 'Single-leg glute bridge', 'Ξαπλωμένοι ανάσκελα, τεντώστε το ένα πόδι και σπρώξτε με την άλλη φτέρνα για να σηκώσετε τους γοφούς, κρατώντας τη λεκάνη ίσια. Εκπνεύστε στην κορυφή και κατεβείτε ελεγχόμενα.', 'Lying on your back, extend one leg and drive through the other heel to lift the hips, keeping the pelvis level. Exhale at the top and lower with control.', 'home', 'advanced', array['glutes','hamstrings','core']::text[], null, null),
  ('808962f0-8688-3a60-de11-c3846df356c5'::uuid, 'single-leg-pedalling', 'Πετάλι με ένα πόδι', 'Single-leg pedalling', 'Σε προπονητήριο, βγάλτε το ένα πόδι και κάντε ομαλούς κύκλους με το άλλο για 30 δευτερόλεπτα, τραβώντας στο κάτω μέρος και περνώντας από το πάνω. Αλλάξτε πόδι και αναπνέετε ομοιόμορφα.', 'On a trainer, unclip one foot and pedal smooth circles with the other for 30 seconds, pulling through the bottom and over the top. Switch legs and breathe evenly.', 'cycling', 'beginner', array['quads','hamstrings','hip-flexors']::text[], 'Ποδήλατο', 'Bicycle'),
  ('5c5a4cd6-e812-bcbc-4fa3-cd0c780823bd'::uuid, 'skipping-rope', 'Σχοινάκι', 'Jump rope', 'Αναπηδάτε ελαφρά στις μύτες των ποδιών με τους αγκώνες κοντά στο σώμα και τους καρπούς να γυρίζουν το σχοινί. Κρατήστε τα άλματα χαμηλά και την αναπνοή σταθερή.', 'Bounce lightly on the balls of the feet with the elbows close to the body and the wrists turning the rope. Keep the jumps small and breathe steadily.', 'home', 'advanced', array['cardio','calves']::text[], 'Σχοινάκι', 'Jump rope'),
  ('67bf4a26-201f-2be4-2f22-4ec8ff32b36d'::uuid, 'spin-down-5min', 'Ξεκούραστο πετάλι αποθεραπείας, 5 λεπτά', 'Spin-down, 5 min', 'Βάλτε την πιο ελαφριά σχέση και κάντε ελαφρύ πετάλι για 5 λεπτά, αφήνοντας τον καρδιακό ρυθμό να πέσει. Αναπνέετε αργά και χαλαρώστε τα χέρια ένα-ένα.', 'Shift to the easiest gear and pedal lightly for 5 minutes, letting the heart rate fall. Breathe slowly and shake out the arms one at a time.', 'cycling', 'beginner', array['cardio']::text[], 'Ποδήλατο', 'Bicycle'),
  ('7f48fbb6-3fdc-a60c-38a3-9ebf14e5718a'::uuid, 'sprint-intervals-30s', 'Διαλείμματα σπριντ, 30 δευτερόλεπτα', 'Sprint intervals, 30 s', 'Από κίνηση, σπριντάρετε στο μέγιστο για 30 δευτερόλεπτα όρθιοι και μετά καθιστοί, με 4–5 λεπτά χαλαρό πετάλι ανάμεσα. Εκπνεύστε δυνατά· κρατήστε το ποδήλατο ίσιο.', 'From a rolling start, sprint all-out for 30 seconds out of the saddle then seated, with 4–5 minutes of easy spinning between. Exhale hard; keep the bike straight.', 'cycling', 'advanced', array['quads','glutes','calves','cardio']::text[], 'Ποδήλατο', 'Bicycle'),
  ('dcbb70cc-1dbd-ba04-e966-3362b6b8a822'::uuid, 'standing-climb-drill', 'Άσκηση όρθιας ανάβασης', 'Standing climb drill', 'Ανεβείτε δύο σχέσεις, σηκωθείτε στα πετάλια και κουνήστε απαλά το ποδήλατο κάτω σας για 30–60 δευτερόλεπτα, με τους γοφούς πάνω από τα πετάλια. Εκπνεύστε σε κάθε πάτημα.', 'Shift up two gears, stand on the pedals and rock the bike gently beneath you for 30–60 seconds, hips over the cranks. Exhale on each downstroke.', 'cycling', 'intermediate', array['quads','glutes','calves','core']::text[], 'Ποδήλατο', 'Bicycle'),
  ('c882b2f6-55d1-1351-3925-f88a6dddb9c9'::uuid, 'standing-hamstring-stretch', 'Διάταση οπίσθιων μηριαίων όρθια', 'Standing hamstring stretch', 'Ακουμπήστε τη μία φτέρνα σε χαμηλό σκαλί με το πόδι τεντωμένο, σκύψτε από τους γοφούς με ίσια πλάτη μέχρι να τεντώσει ο οπίσθιος μηριαίος. Αναπνέετε αργά και κρατήστε 30 δευτερόλεπτα ανά πλευρά.', 'Place one heel on a low step with the leg straight, hinge forward from the hips with a flat back until the hamstring stretches. Breathe slowly and hold 30 seconds each side.', 'running', 'intermediate', array['hamstrings','calves']::text[], null, null),
  ('ba0e3cc4-7d2e-38d6-85f9-1b04657844ca'::uuid, 'standing-quad-stretch', 'Διάταση τετρακεφάλου όρθια', 'Standing quad stretch', 'Κρατηθείτε από τοίχο αν χρειάζεται, φέρτε τη μία φτέρνα προς τους γλουτούς και κρατήστε τα γόνατα ενωμένα. Γείρετε ελαφρά τη λεκάνη και αναπνέετε αργά για 20–30 δευτερόλεπτα σε κάθε πλευρά.', 'Hold a wall if needed, bring one heel toward the glutes and keep the knees together. Tuck the pelvis slightly and breathe slowly for 20–30 seconds each side.', 'home', 'beginner', array['quads','hip-flexors']::text[], null, null),
  ('1461d1a6-cca8-9421-6664-688a7638c546'::uuid, 'stationary-bike-cooldown', 'Αποθεραπεία σε στατικό ποδήλατο', 'Stationary bike cool-down', 'Κάντε πετάλι χαλαρά με ελαφριά αντίσταση για λίγα λεπτά, αφήνοντας τον καρδιακό ρυθμό να πέσει. Αναπνέετε αργά και χαλαρώστε τους ώμους.', 'Pedal easily with light resistance for a few minutes, letting the heart rate come down. Breathe slowly and relax the shoulders.', 'gym', 'beginner', array['cardio']::text[], 'Μηχάνημα', 'Machine'),
  ('30474597-4778-ad84-de54-82b21c73ad0d'::uuid, 'steady-ride-20min', 'Σταθερή διαδρομή, 20 λεπτά', 'Steady ride, 20 min', 'Οδηγήστε σε ρυθμό που μπορείτε να συζητάτε, με ομαλό πετάλι και ακίνητο πάνω μέρος του σώματος. Αναπνέετε ομοιόμορφα και πίνετε τακτικά νερό.', 'Ride at a pace where you can hold a conversation, keeping the cadence smooth and the upper body still. Breathe evenly and drink regularly.', 'cycling', 'beginner', array['cardio','quads','glutes']::text[], 'Ποδήλατο', 'Bicycle'),
  ('f03c0929-0510-1515-73f0-6707f00dcbe2'::uuid, 'streamline-glide-stretch', 'Διάταση streamline', 'Streamline glide stretch', 'Σπρώξτε από τον τοίχο σε σφιχτό streamline, παλάμες η μία πάνω στην άλλη και χέρια να πιέζουν τα αυτιά, και γλιστρήστε μέχρι να επιβραδύνετε. Εκπνεύστε αργά στο γλίστρημα και επαναλάβετε ως χαλαρωτικό κλείσιμο.', 'Push off the wall in a tight streamline, hands stacked and arms squeezing the ears, and glide until you slow. Exhale slowly through the glide and repeat as a relaxing finisher.', 'swimming', 'advanced', array['shoulders','back','core']::text[], null, null),
  ('4b6f0c23-b78a-df17-a8ad-7690ffe59a56'::uuid, 'strides-100m', 'Strides 100 μέτρων', 'Strides, 100 m', 'Επιταχύνετε ομαλά για 100 μέτρα μέχρι περίπου το 85% της προσπάθειας, τρέξτε όρθιοι και χαλαροί, μετά περπατήστε πίσω για αποκατάσταση. Αναπνέετε ελεύθερα· είναι γρήγορα αλλά όχι στο μέγιστο.', 'Accelerate smoothly over 100 m to about 85% effort, run tall and relaxed, then walk back to recover. Breathe freely; these are fast but not all-out.', 'running', 'intermediate', array['cardio','quads','hamstrings','calves']::text[], null, null),
  ('b365dbf3-28d5-34b0-fb00-16cfae9f4ea2'::uuid, 'supine-knee-hug', 'Αγκάλιασμα γονάτων στο στήθος', 'Knees-to-chest hug', 'Ξαπλώστε ανάσκελα, αγκαλιάστε τα δύο γόνατα προς το στήθος και κουνηθείτε απαλά δεξιά-αριστερά. Αναπνέετε αργά και αφήστε τη μέση να χαλαρώσει.', 'Lie on your back, hug both knees toward the chest and rock gently side to side. Breathe slowly and let the lower back release.', 'mobility', 'beginner', array['back','glutes']::text[], 'Στρώμα', 'Mat'),
  ('340c4fe2-89c1-ecea-a131-99761e4deeb6'::uuid, 'tempo-ride-20min', 'Tempo διαδρομή, 20 λεπτά', 'Tempo ride, 20 min', 'Οδηγήστε σε άνετα σκληρή, σταθερή προσπάθεια — μόνο σύντομες φράσεις — με ρυθμό 85–95 στροφών. Κρατήστε χαλαρό το πάνω σώμα και βαθιά, ομοιόμορφη αναπνοή.', 'Ride at a comfortably hard, steady effort — short phrases only — holding a cadence of 85–95 rpm. Keep the upper body relaxed and breathe deep and even.', 'cycling', 'intermediate', array['cardio','quads','glutes']::text[], 'Ποδήλατο', 'Bicycle'),
  ('555527f5-bb3b-3790-89fe-43f1a22823b6'::uuid, 'tempo-run-20min', 'Tempo run 20 λεπτών', 'Tempo run, 20 min', 'Τρέξτε σε άνετα σκληρό ρυθμό που θα μπορούσατε να κρατήσετε για περίπου μία ώρα — λίγες λέξεις τη φορά, όχι προτάσεις. Κρατήστε γρήγορη συχνότητα βημάτων και βαθιά, ομοιόμορφη αναπνοή.', 'Run at a comfortably hard pace you could hold for about an hour — a few words at a time, not sentences. Keep the cadence quick and the breathing deep and even.', 'running', 'intermediate', array['cardio','quads','hamstrings','calves']::text[], null, null),
  ('eafe31f3-17aa-1dda-25f4-9f2100a823b8'::uuid, 'thoracic-rotation', 'Περιστροφή θωρακικής μοίρας (ανοιχτό βιβλίο)', 'Thoracic rotation (open book)', 'Ξαπλώστε στο πλάι με γόνατα λυγισμένα στις 90 μοίρες, χέρια ενωμένα μπροστά, και ανοίξτε το πάνω χέρι προς την άλλη πλευρά ακολουθώντας το με το βλέμμα. Εκπνεύστε καθώς ανοίγετε· γόνατα κάτω.', 'Lie on your side with knees bent at 90 degrees, arms stacked in front, and open the top arm across to the other side following it with the eyes. Exhale as you open; keep the knees down.', 'mobility', 'intermediate', array['back','core','shoulders']::text[], 'Στρώμα', 'Mat'),
  ('01430c98-3343-0339-5042-9f039ecfc306'::uuid, 'threshold-ride-2x20min', 'Threshold διαδρομή, 2 × 20 λεπτά', 'Threshold ride, 2 × 20 min', 'Δύο προσπάθειες 20 λεπτών στον σκληρότερο ρυθμό που θα κρατούσατε για μία ώρα, με 5 λεπτά χαλαρά ανάμεσα. Ρυθμός 85–95 στροφών και βαθιά, ελεγχόμενη αναπνοή.', 'Two 20-minute efforts at the hardest pace you could hold for an hour, with 5 minutes easy between. Keep the cadence at 85–95 rpm and the breathing deep and controlled.', 'cycling', 'advanced', array['cardio','quads','glutes','hamstrings']::text[], 'Ποδήλατο', 'Bicycle'),
  ('d22dd23a-32cc-813c-ee81-878b5d8b3ea7'::uuid, 'threshold-run-2x15min', 'Threshold run 2 × 15 λεπτά', 'Threshold run, 2 × 15 min', 'Δύο μπλοκ 15 λεπτών σε ελεγχόμενα σκληρό ρυθμό με 3 λεπτά χαλαρού τζόκινγκ ανάμεσα. Αναπνέετε βαθιά και ρυθμικά· το δεύτερο μπλοκ πρέπει να μοιάζει με το πρώτο.', 'Two 15-minute blocks at a controlled hard pace with 3 minutes of easy jogging between. Breathe deeply and rhythmically; the second block should feel the same as the first.', 'running', 'advanced', array['cardio','quads','hamstrings','calves']::text[], null, null),
  ('2e96a43a-7938-ffb5-5bea-a8bd05318486'::uuid, 'treadmill-walk-5min', 'Περπάτημα σε διάδρομο, 5 λεπτά', 'Treadmill walk, 5 min', 'Περπατήστε γρήγορα σε ρυθμό που μπορείτε ακόμα να μιλάτε, με τα χέρια να κινούνται ελεύθερα. Αναπνέετε από τη μύτη και αφήστε το σώμα να ζεσταθεί σταδιακά.', 'Walk briskly at a pace where you can still talk, arms swinging freely. Breathe through the nose and let the body warm up gradually.', 'gym', 'beginner', array['cardio']::text[], 'Μηχάνημα', 'Machine'),
  ('f2a3fed7-be7b-2f35-6d5b-f195211e1481'::uuid, 'vo2-intervals-3min', 'Διαλείμματα VO2, 3 λεπτά', 'VO2 intervals, 3 min', 'Οδηγήστε 3 λεπτά πολύ σκληρά στις 95–105 στροφές — το τελευταίο λεπτό πρέπει να είναι πραγματική μάχη — μετά χαλαρό πετάλι 3 λεπτά· επαναλάβετε 4–5 φορές. Βαθιά και γρήγορη αναπνοή, χαλαροί ώμοι.', 'Ride 3 minutes very hard at 95–105 rpm — the last minute should be a real fight — then spin easy for 3 minutes; repeat 4–5 times. Breathe deep and fast, shoulders relaxed.', 'cycling', 'advanced', array['cardio','quads','glutes']::text[], 'Ποδήλατο', 'Bicycle'),
  ('88de81aa-b57e-b13e-e159-967e57dfc476'::uuid, 'walk-jog-intervals', 'Διαλείμματα περπάτημα–τζόκινγκ (1 λεπτό τζόκινγκ / 2 λεπτά περπάτημα)', 'Walk–jog intervals (1 min jog / 2 min walk)', 'Τρέξτε αργά για ένα λεπτό σε ρυθμό που μπορείτε να μιλάτε με ολόκληρες προτάσεις, μετά περπατήστε δύο λεπτά για αποκατάσταση. Προσγειωθείτε ελαφρά κάτω από τους γοφούς και αναπνέετε ρυθμικά.', 'Jog slowly for one minute at a pace where you could speak in full sentences, then walk for two to recover. Land lightly under the hips and breathe rhythmically.', 'running', 'beginner', array['cardio','quads','calves']::text[], null, null),
  ('4ff51d1c-e2ee-bc85-62c7-8d75c5237253'::uuid, 'walking-lunge-dumbbells', 'Προβολές βάδην με αλτήρες', 'Walking lunge with dumbbells', 'Κάντε βήμα μπροστά σε προβολή με τα δύο γόνατα κοντά στις 90 μοίρες, κορμός όρθιος, και σπρώξτε με τη μπροστινή φτέρνα στο επόμενο βήμα. Εκπνεύστε καθώς σηκώνεστε.', 'Step forward into a lunge with both knees near 90 degrees, torso upright, then drive through the front heel into the next step. Breathe out as you rise.', 'gym', 'intermediate', array['quads','glutes','hamstrings']::text[], 'Αλτήρες', 'Dumbbells'),
  ('c0c9d9ea-22fe-426a-e7b8-f9fcebcb43f0'::uuid, 'wall-push-up', 'Κάμψεις στον τοίχο', 'Wall push-up', 'Χέρια στον τοίχο στο ύψος του στήθους, σώμα σε ευθεία γραμμή. Λυγίστε τους αγκώνες φέρνοντας το στήθος προς τον τοίχο, εκπνεύστε καθώς σπρώχνετε.', 'Hands on the wall at chest height, body in a straight line. Bend the elbows to bring the chest toward the wall, exhale as you push away.', 'home', 'beginner', array['chest','triceps','shoulders']::text[], null, null),
  ('3cc8244a-d8b3-0240-0efc-e602f68b7277'::uuid, 'wall-shoulder-flexion-slides', 'Ολισθήσεις ώμων στον τοίχο', 'Wall shoulder flexion slides', 'Πλάτη και κεφάλι στον τοίχο, σύρετε το πίσω μέρος των πήχεων πάνω στον τοίχο κρατώντας τα πλευρά κάτω και τους καρπούς σε επαφή. Εκπνεύστε καθώς ανεβαίνουν τα χέρια· σταματήστε όπου χάνεται η επαφή.', 'Back and head against the wall, slide the backs of the forearms up the wall keeping the ribs down and the wrists in contact. Exhale as the arms rise; stop where contact breaks.', 'mobility', 'advanced', array['shoulders','back']::text[], null, null),
  ('3077fc5c-8aec-7c3c-13fe-926f6ac084b5'::uuid, 'weighted-pull-up', 'Έλξεις με βάρος', 'Weighted pull-up', 'Κρεμαστείτε με πρόσθετο βάρος σε ζώνη, τραβήξτε μέχρι το πηγούνι να περάσει τη μπάρα με τους αγκώνες να κατεβαίνουν, κατεβείτε πλήρως. Εκπνεύστε στο τράβηγμα και αποφύγετε την αιώρηση.', 'Hang with added weight on a belt, pull until the chin clears the bar with the elbows driving down, lower fully. Exhale on the pull and avoid swinging.', 'gym', 'advanced', array['back','biceps','core']::text[], 'Μονόζυγο', 'Pull-up bar'),
  ('ef241eb6-0c31-7039-817e-7b6996c1911a'::uuid, 'worlds-greatest-stretch', 'Η μεγαλύτερη διάταση του κόσμου', 'World''s greatest stretch', 'Κάντε μακριά προβολή, ακουμπήστε το αντίθετο χέρι κάτω, γυρίστε το άλλο χέρι προς το ταβάνι και μετά κατεβάστε τον αγκώνα μέσα από το μπροστινό πόδι. Εκπνεύστε σε κάθε περιστροφή· εναλλάξ πλευρές.', 'Step into a long lunge, place the opposite hand down, rotate the other arm toward the ceiling, then drop the elbow inside the front foot. Exhale on each rotation; alternate sides.', 'mobility', 'intermediate', array['hip-flexors','hamstrings','back','shoulders']::text[], null, null),
  ('8f90e21a-ec2a-e11b-02a8-9cfa5d37a8e1'::uuid, 'wrist-circles', 'Κύκλοι καρπών', 'Wrist circles', 'Πλέξτε τα δάχτυλα και γυρίστε τους καρπούς αργά προς τις δύο κατευθύνσεις, μετά πιέστε τις παλάμες στο πάτωμα στα τέσσερα για ήπια διάταση. Αναπνέετε άνετα.', 'Interlace the fingers and roll the wrists slowly in both directions, then press the palms to the floor on all fours for a gentle stretch. Breathe easily.', 'calisthenics', 'beginner', array['forearms']::text[], null, null)
